#import "GenericEvidenceSource.h"

@interface FocusEvidenceSource : GenericEvidenceSource
@end

//
//  FocusEvidenceSource.m
//  ControlPlane
//
//  Reads Focus status via INFocusStatusCenter (public Intents API). Does not
//  write private Notification Center DND preferences (#113 / #34 B).
//
//  IMPORTANT: This code is intended to be compiled for the ARC mode
//

#import <Intents/Intents.h>
#import "FocusEvidenceSource.h"
#import "DSLogger.h"

@implementation FocusEvidenceSource {
	BOOL focusOn;
	BOOL collected;
}

- (NSString *)description {
	return NSLocalizedString(@"Create rules based on whether Focus (formerly Do Not Disturb) is currently on.", @"");
}

- (void)refreshStatus {
	INFocusStatusCenter *center = [INFocusStatusCenter defaultCenter];
	INFocusStatusAuthorizationStatus auth = center.authorizationStatus;
	if (auth == INFocusStatusAuthorizationStatusNotDetermined) {
		[center requestAuthorizationWithCompletionHandler:^(INFocusStatusAuthorizationStatus status) {
			DSLog(@"Focus status authorization → %ld", (long)status);
		}];
	}
	INFocusStatus *status = center.focusStatus;
	focusOn = status.isFocused;
	collected = YES;
	[self setDataCollected:YES];
}

- (void)start {
	if (running) {
		return;
	}
	[self refreshStatus];
	// Poll periodically; Focus notifications are not always delivered to agents.
	[NSTimer scheduledTimerWithTimeInterval:15.0
					 target:self
				       selector:@selector(timerFired:)
				       userInfo:nil
					repeats:YES];
	running = YES;
}

- (void)timerFired:(NSTimer *)timer {
	(void)timer;
	BOOL was = focusOn;
	[self refreshStatus];
	if (was != focusOn) {
		[[NSNotificationCenter defaultCenter] postNotificationName:@"evidenceSourceDataDidChange" object:nil];
	}
}

- (void)stop {
	if (!running) {
		return;
	}
	collected = NO;
	[self setDataCollected:NO];
	running = NO;
}

- (NSString *)name {
	return @"Focus";
}

- (BOOL)doesRuleMatch:(NSDictionary *)rule {
	if (!collected) {
		return NO;
	}
	NSString *param = rule[@"parameter"];
	if ([param isEqualToString:@"on"]) {
		return focusOn;
	}
	if ([param isEqualToString:@"off"]) {
		return !focusOn;
	}
	return NO;
}

- (NSString *)getSuggestionLeadText:(NSString *)type {
	(void)type;
	return NSLocalizedString(@"Focus is", @"In rule-adding dialog");
}

- (NSArray *)getSuggestions {
	return @[
		@{ @"type": @"Focus", @"parameter": @"on",
		   @"description": NSLocalizedString(@"On", @"") },
		@{ @"type": @"Focus", @"parameter": @"off",
		   @"description": NSLocalizedString(@"Off", @"") },
	];
}

- (NSString *)friendlyName {
	return NSLocalizedString(@"Focus", @"");
}

@end

//
//  SetFocusAction.h
//  ControlPlane
//
//  Set Focus by running a user Shortcut that changes Focus (#113).
//

#import "Action.h"

@interface SetFocusAction : Action <ActionWithString>
@end

//
//  SetFocusAction.m
//  ControlPlane
//
//  Invokes a Shortcuts shortcut that sets Focus (public path; no private DND
//  prefs). Parameter is the Shortcut name or ID — same transport as Run Shortcut.
//
//  IMPORTANT: This code is intended to be compiled for the ARC mode
//

#import "DSLogger.h"
#import "SetFocusAction.h"

static NSString * const kShortcutsCLIPath = @"/usr/bin/shortcuts";

@implementation SetFocusAction {
	NSString *shortcutNameOrID;
}

+ (BOOL)isActionApplicableToSystem {
	return [[NSFileManager defaultManager] isExecutableFileAtPath:kShortcutsCLIPath];
}

- (id)init {
	self = [super init];
	if (!self) {
		return nil;
	}
	shortcutNameOrID = @"";
	return self;
}

- (id)initWithDictionary:(NSDictionary *)dict {
	self = [super initWithDictionary:dict];
	if (!self) {
		return nil;
	}
	shortcutNameOrID = [dict[@"parameter"] copy] ?: @"";
	return self;
}

- (NSMutableDictionary *)dictionary {
	NSMutableDictionary *dict = [super dictionary];
	dict[@"parameter"] = [shortcutNameOrID copy] ?: @"";
	return dict;
}

- (NSString *)description {
	return [NSString stringWithFormat:NSLocalizedString(@"Set Focus via Shortcut '%@'.", @""),
		shortcutNameOrID];
}

- (BOOL)execute:(NSString **)errorString {
	NSString *trimmed = [shortcutNameOrID stringByTrimmingCharactersInSet:
		[NSCharacterSet whitespaceAndNewlineCharacterSet]];
	if (trimmed.length == 0) {
		if (errorString) {
			*errorString = NSLocalizedString(@"Cannot set Focus: Shortcut name or identifier is empty. Create a Shortcut that sets your Focus mode and paste its name here.", @"");
		}
		return NO;
	}
	if (![SetFocusAction isActionApplicableToSystem]) {
		if (errorString) {
			*errorString = NSLocalizedString(@"Cannot set Focus: the shortcuts command-line tool is not available.", @"");
		}
		return NO;
	}

	NSTask *task = [[NSTask alloc] init];
	task.executableURL = [NSURL fileURLWithPath:kShortcutsCLIPath];
	task.arguments = @[ @"run", trimmed ];
	task.standardOutput = [NSPipe pipe];
	task.standardError = [NSPipe pipe];

	NSError *launchError = nil;
	if (![task launchAndReturnError:&launchError]) {
		DSLog(@"Failed to launch shortcuts for Focus '%@': %@", trimmed, launchError);
		if (errorString) {
			*errorString = [NSString stringWithFormat:
				NSLocalizedString(@"Failed to set Focus via Shortcut '%@'.", @""), trimmed];
		}
		return NO;
	}
	[task waitUntilExit];
	if (task.terminationStatus != 0) {
		if (errorString) {
			*errorString = [NSString stringWithFormat:
				NSLocalizedString(@"Shortcut '%@' failed while setting Focus (exit %d). Check the Shortcut in the Shortcuts app.", @""),
				trimmed, task.terminationStatus];
		}
		return NO;
	}
	return YES;
}

+ (NSString *)helpText {
	return NSLocalizedString(@"The parameter is the name or identifier of a Shortcut that sets Focus (System Settings → Focus). Create the Shortcut once, then reference it here.", @"");
}

+ (NSString *)creationHelpText {
	return NSLocalizedString(@"Set Focus using Shortcut", @"");
}

+ (NSString *)friendlyName {
	return NSLocalizedString(@"Set Focus (via Shortcut)", @"");
}

+ (NSString *)menuCategory {
	return NSLocalizedString(@"System", @"");
}

- (void)setParameter:(NSString *)parameter {
	shortcutNameOrID = [parameter copy] ?: @"";
}

- (NSString *)parameter {
	return [shortcutNameOrID copy] ?: @"";
}

@end

