def unescape(s: str) -> str:
    out = []
    i = 0
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s):
            n = s[i + 1]
            mapping = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\"}
            if n in mapping:
                out.append(mapping[n])
                i += 2
                continue
        out.append(s[i])
        i += 1
    return "".join(out)


def escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def read_catalog(path: Path) -> str:
    raw = path.read_bytes()
    if raw.startswith(b"\xff\xfe") or raw.startswith(b"\xfe\xff"):
        return raw.decode("utf-16")
    return raw.decode("utf-8")


def write_catalog(path: Path, text: str) -> None:
    if not text.endswith("\n"):
        text += "\n"
    path.write_bytes(text.encode("utf-16"))


def parse(text: str) -> dict[str, str]:
    catalog = {}
    for m in re.finditer(r'^"((?:\\.|[^"\\])*)"\s*=\s*"((?:\\.|[^"\\])*)"\s*;', text, re.M):
        catalog[unescape(m.group(1))] = unescape(m.group(2))
    return catalog


def replace_value(text: str, key: str, value: str) -> str:
    esc_key = escape(key)
    pattern = re.compile(
        r'^("' + re.escape(esc_key) + r'"\s*=\s*")((?:\\.|[^"\\])*)("\s*;)',
        re.M,
    )
    repl = '"' + esc_key + '" = "' + escape(value) + '";'
    new, n = pattern.subn(repl, text)
    if n == 0:
        raise SystemExit(f"failed to replace existing key: {key[:80]}")
    return new


def main() -> None:
    missing_locale = []
    for key, locmap in T.items():
        for loc in LOCALES:
            if loc == "en":
                continue
            if loc not in locmap:
                missing_locale.append((loc, key[:60]))
    if missing_locale:
        raise SystemExit(f"incomplete translations: {missing_locale[:5]}")

    for loc in LOCALES:
        path = ROOT / f"Resources/{loc}.lproj/Localizable.strings"
        text = read_catalog(path)
        catalog = parse(text)
        added = 0
        updated = 0
        appendix = ["", "/* Issue #131 Focus, Power, Settings, Shortcuts, gated actions */"]
        for key, locmap in T.items():
            value = key if loc == "en" else locmap[loc]
            if key not in catalog:
                appendix.append(f'"{escape(key)}" = "{escape(value)}";')
                added += 1
            elif catalog[key] != value and loc != "en":
                text = replace_value(text, key, value)
                catalog[key] = value
                updated += 1
        if added:
            text = text.rstrip() + "\n" + "\n".join(appendix) + "\n"
        write_catalog(path, text)
        print(f"{loc}: added {added}, updated {updated}")


if __name__ == "__main__":
    main()
